\item[S2] Mini-Workshop: Dynamical versus Diffraction Spectra in the Theory of Quasicrystals (2014), Oberwolfach Reports, DOI 10.4171/owr/2014/53, pp. 2987--3013. Primary report accessed 2026-10-11; relevant PDF pages 9, 10.
\url{https://doi.org/10.4171/owr/2014/53}.
\item[S3] Taati and Miękisz, finite-range quasicrystalline Gibbs states (catalogue-listed context; not independently consulted in this preparation).
\url{https://arxiv.org/abs/2512.24436}.
\end{itemize}
